package com.google.common.collect;

import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.assertThrows;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.function.Function;
import org.junit.Test;

public class IteratorsTransformWithJdkFunctionTest {

  @Test
  public void testTransform_basic() {
    Iterator<String> fromIterator = Arrays.asList("1", "2", "3").iterator();
    Function<String, Integer> function = Integer::valueOf;
    Iterator<Integer> transformed = Iterators.transform(fromIterator, function);

    List<Integer> result = new ArrayList<>();
    while (transformed.hasNext()) {
      result.add(transformed.next());
    }

    assertThat(result).containsExactly(1, 2, 3).inOrder();
  }

  @Test
  public void testTransform_remove() {
    List<String> source = new ArrayList<>(Arrays.asList("a", "b", "c"));
    Iterator<String> fromIterator = source.iterator();
    Function<String, String> function = String::toUpperCase;
    Iterator<String> transformed = Iterators.transform(fromIterator, function);

    assertThat(transformed.next()).isEqualTo("A");
    transformed.remove();
    assertThat(source).containsExactly("b", "c").inOrder();

    assertThat(transformed.next()).isEqualTo("B");
    transformed.remove();
    assertThat(source).containsExactly("c").inOrder();

    assertThat(transformed.next()).isEqualTo("C");
    transformed.remove();
    assertThat(source).isEmpty();
    assertThat(transformed.hasNext()).isFalse();
  }

  @Test
  public void testTransform_exception() {
    Iterator<String> fromIterator = Arrays.asList("1", "2", "3").iterator();
    Function<String, Integer> function =
        input -> {
          if ("2".equals(input)) {
            throw new IllegalArgumentException("Cannot transform 2");
          }
          return Integer.valueOf(input);
        };
    Iterator<Integer> transformed = Iterators.transform(fromIterator, function);

    assertThat(transformed.next()).isEqualTo(1);
    IllegalArgumentException e = assertThrows(IllegalArgumentException.class, transformed::next);
    assertThat(e).hasMessageThat().isEqualTo("Cannot transform 2");
    // Iterator should still be in a consistent state after exception
    assertThat(transformed.hasNext()).isTrue();
    assertThat(transformed.next()).isEqualTo(3);
    assertThat(transformed.hasNext()).isFalse();
  }

  @Test
  public void testTransform_emptyIterator() {
    Iterator<String> fromIterator = Arrays.<String>asList().iterator();
    Function<String, String> function = String::toUpperCase;
    Iterator<String> transformed = Iterators.transform(fromIterator, function);

    assertThat(transformed.hasNext()).isFalse();
    assertThrows(NoSuchElementException.class, transformed::next);
  }

  @Test
  public void testTransform_nullFunction() {
    Iterator<String> fromIterator = Arrays.asList("a", "b").iterator();
    assertThrows(NullPointerException.class, () -> Iterators.transform(fromIterator, null));
  }

  @Test
  public void testTransform_nullElements() {
    List<String> source = Arrays.asList("a", null, "c");
    Iterator<String> fromIterator = source.iterator();
    Function<String, String> function = s -> s == null ? "NULL" : s.toUpperCase();
    Iterator<String> transformed = Iterators.transform(fromIterator, function);

    assertThat(transformed.next()).isEqualTo("A");
    assertThat(transformed.next()).isEqualTo("NULL");
    assertThat(transformed.next()).isEqualTo("C");
    assertThat(transformed.hasNext()).isFalse();
  }
}

