package com.google.common.util.concurrent;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.io.IOException;
import java.util.concurrent.Callable;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;

/**
 * Unit tests for {@link RetryExecutor}.
 */
public class RetryExecutorTest {

    @Test
    public void testBuilderDefaults() {
        RetryExecutor executor = RetryExecutor.builder().build();
        // Defaults are maxRetries=3, backoffMillis=1000, exponentialBackoff=false, retryableExceptions empty
        // We can't directly inspect fields, but we can test behavior
        AtomicInteger attempts = new AtomicInteger();
        Callable<String> task = () -> {
            attempts.incrementAndGet();
            throw new IOException("test");
        };

        Exception e = assertThrows(IOException.class, () -> executor.execute(task));
        assertEquals("test", e.getMessage());
        // Should have tried maxRetries times (default 3)
        assertEquals(3, attempts.get());
    }

    @Test
    public void testMaxRetries() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(5)
                .build();

        AtomicInteger attempts = new AtomicInteger();
        Callable<String> task = () -> {
            attempts.incrementAndGet();
            throw new IOException("test");
        };

        assertThrows(IOException.class, () -> executor.execute(task));
        assertEquals(5, attempts.get());
    }

    @Test
    public void testZeroMaxRetries() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> RetryExecutor.builder().maxRetries(0).build());
        assertEquals("maxRetries must be positive", e.getMessage());
    }

    @Test
    public void testNegativeBackoffMillis() {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class,
                () -> RetryExecutor.builder().backoffMillis(-1).build());
        assertEquals("backoffMillis must be non-negative", e.getMessage());
    }

    @Test
    public void testFixedBackoff() throws Exception {
        final long expectedDelay = 500;
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(2)
                .backoffMillis(expectedDelay)
                .exponentialBackoff(false)
                .build();

        AtomicInteger attempts = new AtomicInteger();
        AtomicLong lastTime = new AtomicLong();
        Callable<String> task = () -> {
            int attempt = attempts.incrementAndGet();
            long currentTime = System.currentTimeMillis();
            if (attempt > 1) {
                long elapsed = currentTime - lastTime.get();
                // Allow some tolerance for timing
                assertTrue("Expected delay of ~" + expectedDelay + "ms, got " + elapsed,
                        elapsed >= expectedDelay && elapsed < expectedDelay + 100);
            }
            lastTime.set(currentTime);
            throw new IOException("test");
        };

        assertThrows(IOException.class, () -> executor.execute(task));
        assertEquals(2, attempts.get());
    }

    @Test
    public void testExponentialBackoff() throws Exception {
        final long baseDelay = 100;
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(4)
                .backoffMillis(baseDelay)
                .exponentialBackoff(true)
                .build();

        AtomicInteger attempts = new AtomicInteger();
        AtomicLong lastTime = new AtomicLong();
        Callable<String> task = () -> {
            int attempt = attempts.incrementAndGet();
            long currentTime = System.currentTimeMillis();
            if (attempt > 1) {
                long elapsed = currentTime - lastTime.get();
                long expectedDelay = (long) (Math.pow(2, attempt - 2) * baseDelay);
                // Allow some tolerance for timing
                assertTrue("Expected delay of ~" + expectedDelay + "ms, got " + elapsed,
                        elapsed >= expectedDelay && elapsed < expectedDelay + 100);
            }
            lastTime.set(currentTime);
            throw new IOException("test");
        };

        assertThrows(IOException.class, () -> executor.execute(task));
        assertEquals(4, attempts.get());
    }

    @Test
    public void testRetryOnSpecificException() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(2)
                .retryOn(IOException.class)
                .build();

        AtomicInteger attempts = new AtomicInteger();
        Callable<String> task = () -> {
            attempts.incrementAndGet();
            throw new IOException("test");
        };

        assertThrows(IOException.class, () -> executor.execute(task));
        // Should retry on IOException
        assertEquals(2, attempts.get());
    }

    @Test
    public void testNoRetryOnNonSpecifiedException() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .retryOn(IOException.class)
                .build();

        AtomicInteger attempts = new AtomicInteger();
        Callable<String> task = () -> {
            attempts.incrementAndGet();
            throw new RuntimeException("test");
        };

        RuntimeException e = assertThrows(RuntimeException.class, () -> executor.execute(task));
        assertEquals("test", e.getMessage());
        // Should not retry on RuntimeException
        assertEquals(1, attempts.get());
    }

    @Test
    public void testMultipleRetryOnExceptions() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(2)
                .retryOn(IOException.class)
                .retryOn(IllegalArgumentException.class)
                .build();

        AtomicInteger attempts = new AtomicInteger();
        Callable<String> task = () -> {
            attempts.incrementAndGet();
            if (attempts.get() == 1) {
                throw new IOException("test1");
            } else {
                throw new IllegalArgumentException("test2");
            }
        };

        Exception e = assertThrows(Exception.class, () -> executor.execute(task));
        // Should retry on both exception types
        assertEquals(2, attempts.get());
        assertTrue(e instanceof IllegalArgumentException);
        assertEquals("test2", e.getMessage());
    }

    @Test
    public void testSuccessOnRetry() throws Exception {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(10)
                .build();

        AtomicInteger attempts = new AtomicInteger();
        Callable<String> task = () -> {
            int attempt = attempts.incrementAndGet();
            if (attempt < 3) {
                throw new IOException("attempt " + attempt);
            }
            return "success";
        };

        String result = executor.execute(task);
        assertEquals("success", result);
        assertEquals(3, attempts.get());
    }

    @Test
    public void testNullTask() {
        RetryExecutor executor = RetryExecutor.builder().build();
        NullPointerException e = assertThrows(NullPointerException.class,
                () -> executor.execute(null));
        assertEquals("task must not be null", e.getMessage());
    }

    @Test
    public void testInterruptedException() {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(1000)
                .build();

        AtomicInteger attempts = new AtomicInteger();
        Callable<String> task = () -> {
            attempts.incrementAndGet();
            throw new IOException("test");
        };

        // Simulate interruption by creating a thread that interrupts itself during sleep
        Thread testThread = new Thread(() -> {
            try {
                executor.execute(task);
                fail("Expected exception");
            } catch (Exception e) {
                // Should throw the last exception (IOException) when interrupted
                assertTrue(e instanceof IOException);
                assertEquals("test", e.getMessage());
            }
        });

        // Start thread and immediately interrupt it
        testThread.start();
        testThread.interrupt();

        try {
            testThread.join(2000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        // Should have attempted at least once
        assertTrue(attempts.get() >= 1);
    }

    @Test
    public void testZeroBackoff() throws Exception {
        RetryExecutor executor = RetryExecutor.builder()
                .maxRetries(3)
                .backoffMillis(0)
                .build();

        AtomicInteger attempts = new AtomicInteger();
        long startTime = System.currentTimeMillis();
        Callable<String> task = () -> {
            attempts.incrementAndGet();
            if (attempts.get() < 3) {
                throw new IOException("test");
            }
            return "success";
        };

        String result = executor.execute(task);
        long elapsed = System.currentTimeMillis() - startTime;
        assertEquals("success", result);
        assertEquals(3, attempts.get());
        // With 0 backoff, execution should be very fast
        assertTrue("Elapsed time should be small with 0 backoff: " + elapsed + "ms", elapsed < 100);
    }

    @Test
    public void testBuilderChaining() {
        RetryExecutor.Builder builder = RetryExecutor.builder()
                .maxRetries(5)
                .backoffMillis(200)
                .exponentialBackoff(true)
                .retryOn(IOException.class)
                .retryOn(RuntimeException.class);

        RetryExecutor executor = builder.build();
        assertNotNull(executor);

        // Test that the built executor works as configured
        AtomicInteger attempts = new AtomicInteger();
        Callable<String> task = () -> {
            attempts.incrementAndGet();
            throw new IOException("test");
        };

        assertThrows(IOException.class, () -> executor.execute(task));
        assertEquals(5, attempts.get());
    }
}

