public class EvictingQueueTest {
    @Test
    public void testAddWhenMaxSizeZeroReturnsFalse() {
        EvictingQueue<String> queue = EvictingQueue.create(0);
        boolean result = queue.add("hello");
        assertThat(result).isFalse();
        assertThat(queue).isEmpty();
        assertThat(queue.contains("hello")).isFalse();
        assertThat(queue.size()).isEqualTo(0);
    }

    @Test
    public void testOfferWhenMaxSizeZeroReturnsFalse() {
        EvictingQueue<String> queue = EvictingQueue.create(0);
        boolean result = queue.offer("world");
        assertThat(result).isFalse();
        assertThat(queue).isEmpty();
        assertThat(queue.contains("world")).isFalse();
        assertThat(queue.size()).isEqualTo(0);
    }

    @Test
    public void testAddWhenMaxSizeZeroMultipleCalls() {
        EvictingQueue<Integer> queue = EvictingQueue.create(0);
        for (int i = 0; i < 10; i++) {
            assertThat(queue.add(i)).isFalse();
        }
        assertThat(queue).isEmpty();
        assertThat(queue.size()).isEqualTo(0);
    }

    @Test
    public void testOfferWhenMaxSizeZeroMultipleCalls() {
        EvictingQueue<Integer> queue = EvictingQueue.create(0);
        for (int i = 0; i < 10; i++) {
            assertThat(queue.offer(i)).isFalse();
        }
        assertThat(queue).isEmpty();
        assertThat(queue.size()).isEqualTo(0);
    }

    @Test
    public void testAddWhenMaxSizeZeroWithNull() {
        EvictingQueue<Object> queue = EvictingQueue.create(0);
        try {
            queue.add(null);
            throw new AssertionError("Expected NullPointerException");
        } catch (NullPointerException expected) {
            // expected because checkNotNull is called before the maxSize check
        }
    }

    @Test
    public void testOfferWhenMaxSizeZeroWithNull() {
        EvictingQueue<Object> queue = EvictingQueue.create(0);
        try {
            queue.offer(null);
            throw new AssertionError("Expected NullPointerException");
        } catch (NullPointerException expected) {
            // expected because checkNotNull is called before the maxSize check
        }
    }

    @Test
    public void testAddWhenMaxSizeNonZeroReturnsTrue() {
        EvictingQueue<String> queue = EvictingQueue.create(3);
        assertThat(queue.add("a")).isTrue();
        assertThat(queue).containsExactly("a");
        assertThat(queue.add("b")).isTrue();
        assertThat(queue).containsExactly("a", "b");
        assertThat(queue.add("c")).isTrue();
        assertThat(queue).containsExactly("a", "b", "c");
        // Eviction should happen, but add should still return true
        assertThat(queue.add("d")).isTrue();
        assertThat(queue).containsExactly("b", "c", "d");
    }

    @Test
    public void testOfferWhenMaxSizeNonZeroReturnsTrue() {
        EvictingQueue<String> queue = EvictingQueue.create(2);
        assertThat(queue.offer("x")).isTrue();
        assertThat(queue).containsExactly("x");
        assertThat(queue.offer("y")).isTrue();
        assertThat(queue).containsExactly("x", "y");
        // Eviction should happen, but offer should still return true
        assertThat(queue.offer("z")).isTrue();
        assertThat(queue).containsExactly("y", "z");
    }

