    public void testAddAndOfferConsistency() {
        EvictingQueue<Integer> queue = EvictingQueue.create(0);
        assertThat(queue.add(1)).isEqualTo(queue.offer(1));
        queue = EvictingQueue.create(5);
        for (int i = 0; i < 10; i++) {
            assertThat(queue.add(i)).isEqualTo(queue.offer(i));
        }
    }
}

