package com.google.common.eventbus;

import static com.google.common.truth.Truth.assertThat;

import com.google.common.collect.ImmutableList;
import java.lang.reflect.Method;
import org.junit.Before;
import org.junit.Test;

/**
 * Tests for {@link Subscriber} specifically for catching StackOverflowError.
 */
public class SubscriberStackOverflowErrorTest {

  private EventBus eventBus;
  private RecordingSubscriberExceptionHandler exceptionHandler;

  @Before
  public void setUp() {
    exceptionHandler = new RecordingSubscriberExceptionHandler();
    eventBus = new EventBus(exceptionHandler);
  }

  @Test
  public void testSubscriberThrowsStackOverflowError() {
    // Create a subscriber that throws StackOverflowError
    Object subscriber = new Object() {
      @Subscribe
      public void handleEvent(Object event) {
        throw new StackOverflowError("Test stack overflow");
      }
    };

    eventBus.register(subscriber);
    Object event = new Object();

    // Post the event - should not throw
    eventBus.post(event);

    // Verify the exception handler was called with StackOverflowError
    assertThat(exceptionHandler.lastException).isInstanceOf(StackOverflowError.class);
    assertThat(exceptionHandler.lastException).hasMessageThat().isEqualTo("Test stack overflow");
    assertThat(exceptionHandler.lastContext.getEvent()).isSameInstanceAs(event);

    // Verify the context has correct information
    SubscriberExceptionContext context = exceptionHandler.lastContext;
    assertThat(context.getEventBus()).isSameInstanceAs(eventBus);
    assertThat(context.getSubscriber()).isSameInstanceAs(subscriber);

    // Check that the method is the correct @Subscribe method
    Method expectedMethod = getSubscribeMethod(subscriber);
    assertThat(context.getSubscriberMethod()).isEqualTo(expectedMethod);
  }

  @Test
  public void testSubscriberThrowsStackOverflowErrorThroughRecursion() {
    // Create a subscriber that causes StackOverflowError through recursion
    RecursiveSubscriber subscriber = new RecursiveSubscriber();
    eventBus.register(subscriber);
    Object event = new Object();

    // Post the event - should not throw
    eventBus.post(event);

    // Verify the exception handler was called with StackOverflowError
    assertThat(exceptionHandler.lastException).isInstanceOf(StackOverflowError.class);
    assertThat(exceptionHandler.lastContext.getEvent()).isSameInstanceAs(event);
  }

  @Test
  public void testSubscriberThrowsInvocationTargetExceptionWithStackOverflowError() {
    // Test that StackOverflowError wrapped in InvocationTargetException is still handled
    // This tests the existing behavior
    Object subscriber = new Object() {
      @Subscribe
      public void handleEvent(Object event) {
        throw new RuntimeException(new StackOverflowError("Nested stack overflow"));
      }
    };

    eventBus.register(subscriber);
    Object event = new Object();

    eventBus.post(event);

    // Should be RuntimeException (not StackOverflowError) because it's wrapped
    assertThat(exceptionHandler.lastException).isInstanceOf(RuntimeException.class);
    assertThat(exceptionHandler.lastException.getCause()).isInstanceOf(StackOverflowError.class);
    assertThat(exceptionHandler.lastException.getCause()).hasMessageThat()
        .isEqualTo("Nested stack overflow");
  }

  @Test
  public void testMultipleSubscribersWithStackOverflowError() {
    // Test that one subscriber throwing StackOverflowError doesn't prevent others from executing
    final StringBuilder executionOrder = new StringBuilder();

    Object subscriber1 = new Object() {
      @Subscribe
      public void handleEvent(Object event) {
        executionOrder.append("1");
        throw new StackOverflowError("First subscriber overflow");
      }
    };

    Object subscriber2 = new Object() {
      @Subscribe
      public void handleEvent(Object event) {
        executionOrder.append("2");
      }
    };

    eventBus.register(subscriber1);
    eventBus.register(subscriber2);

    eventBus.post(new Object());

    // Both subscribers should have been called
    assertThat(executionOrder.toString()).isEqualTo("12");
    assertThat(exceptionHandler.lastException).isInstanceOf(StackOverflowError.class);
    assertThat(exceptionHandler.lastException).hasMessageThat()
        .isEqualTo("First subscriber overflow");
  }

  @Test
  public void testAsyncEventBusWithStackOverflowError() {
    // Test with AsyncEventBus to ensure it works with different executors
    exceptionHandler = new RecordingSubscriberExceptionHandler();
    AsyncEventBus asyncEventBus = new AsyncEventBus(
        java.util.concurrent.Executors.newSingleThreadExecutor(), 
        exceptionHandler);

    Object subscriber = new Object() {
      @Subscribe
      public void handleEvent(Object event) {
        throw new StackOverflowError("Async stack overflow");
      }
    };

    asyncEventBus.register(subscriber);
    Object event = new Object();

    asyncEventBus.post(event);

    // Wait for async execution
    try {
      Thread.sleep(100);
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
    }

    assertThat(exceptionHandler.lastException).isInstanceOf(StackOverflowError.class);
    assertThat(exceptionHandler.lastException).hasMessageThat()
        .isEqualTo("Async stack overflow");
    assertThat(exceptionHandler.lastContext.getEvent()).isSameInstanceAs(event);
  }

  // Helper method to get the @Subscribe method from the anonymous class
  private Method getSubscribeMethod(Object subscriber) {
    for (Method method : subscriber.getClass().getDeclaredMethods()) {
      if (method.isAnnotationPresent(Subscribe.class)) {
        return method;
      }
    }
    throw new AssertionError("No @Subscribe method found");
  }

  // Helper class for testing recursion
  private static class RecursiveSubscriber {
    private int depth = 0;

    @Subscribe
    public void handleEvent(Object event) {
      depth++;
      if (depth > 10000) {
        // This should cause StackOverflowError
        handleEvent(event);
      } else {
        throw new StackOverflowError("Recursive stack overflow");
      }
    }
  }

  // Custom SubscriberExceptionHandler for testing
  private static class RecordingSubscriberExceptionHandler 
      implements SubscriberExceptionHandler {

    Throwable lastException;
    SubscriberExceptionContext lastContext;

    @Override
    public void handleException(Throwable exception, SubscriberExceptionContext context) {
      this.lastException = exception;
      this.lastContext = context;
    }
  }
}

