package com.google.common.eventbus;

import com.google.common.collect.ImmutableList;
import java.lang.reflect.Method;
import java.util.concurrent.Executor;

/**
 * Tests for {@link Subscriber} focusing on the handling of StackOverflowError.
 */
public class SubscriberTest {
  private EventBus eventBus;
  private RecordingSubscriberExceptionHandler exceptionHandler;

  public void setUp() {
    exceptionHandler = new RecordingSubscriberExceptionHandler();
    eventBus = new EventBus(exceptionHandler);
  }

  public void testSubscriberThrowsStackOverflowError() {
    setUp();
    // Create a subscriber that throws StackOverflowError
    Object subscriber = new Object() {
      @Subscribe
      public void handleEvent(Object event) {
        throw new StackOverflowError("Test stack overflow");
      }
    };

    eventBus.register(subscriber);
    eventBus.post(new Object());

    // Verify that the exception handler was called with the StackOverflowError
    ImmutableList<Throwable> capturedExceptions = exceptionHandler.exceptions.build();
    ImmutableList<SubscriberExceptionContext> capturedContexts = exceptionHandler.contexts.build();

    if (capturedExceptions.size() != 1) {
      throw new AssertionError("Expected 1 exception, got " + capturedExceptions.size());
    }
    if (!(capturedExceptions.get(0) instanceof StackOverflowError)) {
      throw new AssertionError("Expected StackOverflowError, got " + capturedExceptions.get(0).getClass());
    }
    if (!capturedExceptions.get(0).getMessage().contains("Test stack overflow")) {
      throw new AssertionError("Expected message containing 'Test stack overflow', got: " + capturedExceptions.get(0).getMessage());
    }
    if (capturedContexts.size() != 1) {
      throw new AssertionError("Expected 1 context, got " + capturedContexts.size());
    }
    if (capturedContexts.get(0).getEvent() == null) {
      throw new AssertionError("Expected event not to be null");
    }
    if (capturedContexts.get(0).getSubscriber() != subscriber) {
      throw new AssertionError("Expected subscriber to be same instance");
    }
    // Verify the method name matches
    Method expectedMethod;
    try {
      expectedMethod = subscriber.getClass().getMethod("handleEvent", Object.class);
    } catch (NoSuchMethodException e) {
      throw new AssertionError(e);
    }
    if (!capturedContexts.get(0).getSubscriberMethod().equals(expectedMethod)) {
      throw new AssertionError("Expected method to match");
    }
  }

  public void testSubscriberThrowsInvocationTargetExceptionWrappingError() {
    setUp();
    // This test ensures that the existing behavior for InvocationTargetException is preserved
    Object subscriber = new Object() {
      @Subscribe
      public void handleEvent(Object event) {
        throw new RuntimeException("Wrapped in InvocationTargetException");
      }
    };

    eventBus.register(subscriber);
    eventBus.post(new Object());

    ImmutableList<Throwable> capturedExceptions = exceptionHandler.exceptions.build();
    if (capturedExceptions.size() != 1) {
      throw new AssertionError("Expected 1 exception, got " + capturedExceptions.size());
    }
    if (!(capturedExceptions.get(0) instanceof RuntimeException)) {
      throw new AssertionError("Expected RuntimeException, got " + capturedExceptions.get(0).getClass());
    }
    if (!capturedExceptions.get(0).getMessage().contains("Wrapped in InvocationTargetException")) {
      throw new AssertionError("Expected message containing 'Wrapped in InvocationTargetException', got: " + capturedExceptions.get(0).getMessage());
    }
  }

  public void testSubscriberThrowsOtherErrorNotCaught() {
    setUp();
    // Other Errors (like OutOfMemoryError) should not be caught and should propagate.
    // We test this by using a direct executor to avoid async complications.
    // Create a custom EventBus with a direct executor
    EventBus directEventBus = new EventBus(
        "test",
        new Executor() {
          @Override
          public void execute(Runnable command) {
            command.run();
          }
        },
        Dispatcher.immediate(),
        exceptionHandler);

    Object subscriber = new Object() {
      @Subscribe
      public void handleEvent(Object event) {
        throw new OutOfMemoryError("Test out of memory");
      }
    };

    directEventBus.register(subscriber);
    // The Error should propagate out of dispatchEvent
    try {
      directEventBus.post(new Object());
      throw new AssertionError("Expected OutOfMemoryError to be thrown");
    } catch (OutOfMemoryError expected) {
      if (!expected.getMessage().contains("Test out of memory")) {
        throw new AssertionError("Expected message containing 'Test out of memory', got: " + expected.getMessage());
      }
    }
    // The exception handler should not have been called
    ImmutableList<Throwable> capturedExceptions = exceptionHandler.exceptions.build();
    if (!capturedExceptions.isEmpty()) {
      throw new AssertionError("Expected no exceptions in handler, got " + capturedExceptions.size());
    }
  }

  public void testSubscriberThrowsStackOverflowErrorWithDirectExecutor() {
    setUp();
    // Use a direct executor to test synchronous execution
    EventBus directEventBus = new EventBus(
        "test",
        new Executor() {
          @Override
          public void execute(Runnable command) {
            command.run();
          }
        },
        Dispatcher.immediate(),
        exceptionHandler);

    Object subscriber = new Object() {
      @Subscribe
      public void handleEvent(Object event) {
        throw new StackOverflowError("Direct executor test");
      }
    };

    directEventBus.register(subscriber);
    // The StackOverflowError should be caught and passed to the handler, not propagated
    directEventBus.post(new Object());

    ImmutableList<Throwable> capturedExceptions = exceptionHandler.exceptions.build();
    if (capturedExceptions.size() != 1) {
      throw new AssertionError("Expected 1 exception, got " + capturedExceptions.size());
    }
    if (!(capturedExceptions.get(0) instanceof StackOverflowError)) {
      throw new AssertionError("Expected StackOverflowError, got " + capturedExceptions.get(0).getClass());
    }
    if (!capturedExceptions.get(0).getMessage().contains("Direct executor test")) {
      throw new AssertionError("Expected message containing 'Direct executor test', got: " + capturedExceptions.get(0).getMessage());
    }
  }

  /**
   * A simple SubscriberExceptionHandler that records the exceptions and contexts for verification.
   */
  private static class RecordingSubscriberExceptionHandler implements SubscriberExceptionHandler {
    final ImmutableList.Builder<Throwable> exceptions = ImmutableList.builder();
    final ImmutableList.Builder<SubscriberExceptionContext> contexts = ImmutableList.builder();

    @Override
