package com.google.common.primitives;

import static com.google.common.truth.Truth.assertThat;

import java.util.Iterator;
import java.util.List;
import java.util.PrimitiveIterator;
import java.util.Spliterator;
import java.util.stream.DoubleStream;
import java.util.stream.IntStream;
import java.util.stream.LongStream;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

@RunWith(JUnit4.class)
public class ImmutableArrayAsListIteratorTest {

  @Test
  public void testImmutableIntArrayAsListIterator() {
    ImmutableIntArray intArray = ImmutableIntArray.of(1, 2, 3, 4, 5);
    List<Integer> asList = intArray.asList();

    // Test that iterator() returns PrimitiveIterator.OfInt
    Iterator<Integer> iterator = asList.iterator();
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfInt.class);

    // Verify we can iterate without boxing using nextInt()
    PrimitiveIterator.OfInt primitiveIterator = (PrimitiveIterator.OfInt) iterator;
    int sum = 0;
    while (primitiveIterator.hasNext()) {
      sum += primitiveIterator.nextInt();
    }
    assertThat(sum).isEqualTo(15);

    // Verify the iterator still works as a regular Iterator<Integer>
    iterator = asList.iterator();
    int boxedSum = 0;
    while (iterator.hasNext()) {
      boxedSum += iterator.next();
    }
    assertThat(boxedSum).isEqualTo(15);
  }

  @Test
  public void testImmutableLongArrayAsListIterator() {
    ImmutableLongArray longArray = ImmutableLongArray.of(10L, 20L, 30L);
    List<Long> asList = longArray.asList();

    // Test that iterator() returns PrimitiveIterator.OfLong
    Iterator<Long> iterator = asList.iterator();
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfLong.class);

    // Verify we can iterate without boxing using nextLong()
    PrimitiveIterator.OfLong primitiveIterator = (PrimitiveIterator.OfLong) iterator;
    long sum = 0L;
    while (primitiveIterator.hasNext()) {
      sum += primitiveIterator.nextLong();
    }
    assertThat(sum).isEqualTo(60L);

    // Verify the iterator still works as a regular Iterator<Long>
    iterator = asList.iterator();
    long boxedSum = 0L;
    while (iterator.hasNext()) {
      boxedSum += iterator.next();
    }
    assertThat(boxedSum).isEqualTo(60L);
  }

  @Test
  public void testImmutableDoubleArrayAsListIterator() {
    ImmutableDoubleArray doubleArray = ImmutableDoubleArray.of(1.5, 2.5, 3.5);
    List<Double> asList = doubleArray.asList();

    // Test that iterator() returns PrimitiveIterator.OfDouble
    Iterator<Double> iterator = asList.iterator();
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfDouble.class);

    // Verify we can iterate without boxing using nextDouble()
    PrimitiveIterator.OfDouble primitiveIterator = (PrimitiveIterator.OfDouble) iterator;
    double sum = 0.0;
    while (primitiveIterator.hasNext()) {
      sum += primitiveIterator.nextDouble();
    }
    assertThat(sum).isWithin(0.0).of(7.5);

    // Verify the iterator still works as a regular Iterator<Double>
    iterator = asList.iterator();
    double boxedSum = 0.0;
    while (iterator.hasNext()) {
      boxedSum += iterator.next();
    }
    assertThat(boxedSum).isWithin(0.0).of(7.5);
  }

  @Test
  public void testImmutableIntArrayAsListIteratorEmpty() {
    ImmutableIntArray emptyArray = ImmutableIntArray.of();
    List<Integer> asList = emptyArray.asList();

    Iterator<Integer> iterator = asList.iterator();
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfInt.class);
    assertThat(iterator.hasNext()).isFalse();
  }

  @Test
  public void testImmutableLongArrayAsListIteratorEmpty() {
    ImmutableLongArray emptyArray = ImmutableLongArray.of();
    List<Long> asList = emptyArray.asList();

    Iterator<Long> iterator = asList.iterator();
    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfLong.class);
    assertThat(iterator.hasNext()).isFalse();
