    assertThat(iterator).isInstanceOf(PrimitiveIterator.OfDouble.class);
    assertThat(iterator.hasNext()).isFalse();
  }

  @Test
  public void testImmutableIntArrayAsListIteratorForEachRemaining() {
    ImmutableIntArray intArray = ImmutableIntArray.of(1, 2, 3);
    List<Integer> asList = intArray.asList();

    PrimitiveIterator.OfInt primitiveIterator = (PrimitiveIterator.OfInt) asList.iterator();
    int[] values = new int[3];
    int[] index = new int[1]; // Use array to work around lambda capture restriction
    primitiveIterator.forEachRemaining((int value) -> {
      values[index[0]++] = value;
    });

    assertThat(values).isEqualTo(new int[]{1, 2, 3});
  }

  @Test
  public void testLegacyApiCompatibility() {
    // Simulate a legacy API that accepts List<Double> but can check for PrimitiveIterator
    List<Double> scores = ImmutableDoubleArray.of(1.0, 2.0, 3.0).asList();

    double sum = 0.0;
    Iterator<Double> iterator = scores.iterator();
    if (iterator instanceof PrimitiveIterator.OfDouble) {
      PrimitiveIterator.OfDouble primitiveIterator = (PrimitiveIterator.OfDouble) iterator;
      while (primitiveIterator.hasNext()) {
        sum += primitiveIterator.nextDouble(); // No boxing
      }
    } else {
      while (iterator.hasNext()) {
        sum += iterator.next(); // Boxing occurs
      }
    }

    assertThat(sum).isWithin(0.0).of(6.0);
  }

