    int[] sum = new int[1];
    intSpliterator.forEachRemaining((int value) -> {
      sum[0] += value;
    });
    assertThat(sum[0]).isEqualTo(15);

    // Test trySplit() - should return null or another primitive spliterator
    spliterator = asList.spliterator();
    Spliterator<Integer> split = spliterator.trySplit();
    if (split != null) {
      assertThat(split).isInstanceOf(Spliterator.OfInt.class);
    }
  }

  @Test
  public void testImmutableLongArrayAsListSpliterator() {
    ImmutableLongArray longArray = ImmutableLongArray.of(10L, 20L, 30L);
    List<Long> asList = longArray.asList();

    // Test that spliterator() returns Spliterator.OfLong
    Spliterator<Long> spliterator = asList.spliterator();
    assertThat(spliterator).isInstanceOf(Spliterator.OfLong.class);

    // Verify we can use it as a primitive spliterator
    Spliterator.OfLong longSpliterator = (Spliterator.OfLong) spliterator;
    long[] sum = new long[1];
    longSpliterator.forEachRemaining((long value) -> {
      sum[0] += value;
    });
    assertThat(sum[0]).isEqualTo(60L);
  }

  @Test
  public void testImmutableDoubleArrayAsListSpliterator() {
    ImmutableDoubleArray doubleArray = ImmutableDoubleArray.of(1.5, 2.5, 3.5);
    List<Double> asList = doubleArray.asList();

    // Test that spliterator() returns Spliterator.OfDouble
    Spliterator<Double> spliterator = asList.spliterator();
    assertThat(spliterator).isInstanceOf(Spliterator.OfDouble.class);

    // Verify we can use it as a primitive spliterator
    Spliterator.OfDouble doubleSpliterator = (Spliterator.OfDouble) spliterator;
    double[] sum = new double[1];
    doubleSpliterator.forEachRemaining((double value) -> {
      sum[0] += value;
    });
    assertThat(sum[0]).isWithin(0.0).of(7.5);
  }

  @Test
  public void testEnhancedForLoop() {
    // Test that enhanced for-loop still works (uses iterator() internally)
    ImmutableIntArray intArray = ImmutableIntArray.of(1, 2, 3);
    List<Integer> asList = intArray.asList();

    int sum = 0;
    for (Integer value : asList) {
      sum += value;
    }
    assertThat(sum).isEqualTo(6);

    // Same for other types
    ImmutableDoubleArray doubleArray = ImmutableDoubleArray.of(1.0, 2.0, 3.0);
    List<Double> doubleList = doubleArray.asList();

    double doubleSum = 0.0;
    for (Double value : doubleList) {
      doubleSum += value;
    }
    assertThat(doubleSum).isWithin(0.0).of(6.0);
  }

  @Test
  public void testIteratorFromSpliteratorsUtility() {
    // Test that the implementation using Spliterators.iterator() works correctly
    ImmutableIntArray intArray = ImmutableIntArray.of(1, 2, 3);
    List<Integer> asList = intArray.asList();

    // Get iterator and verify it works
    Iterator<Integer> iterator = asList.iterator();
    assertThat(iterator.hasNext()).isTrue();
    assertThat(iterator.next()).isEqualTo(1);
    assertThat(iterator.hasNext()).isTrue();
    assertThat(iterator.next()).isEqualTo(2);
    assertThat(iterator.hasNext()).isTrue();
    assertThat(iterator.next()).isEqualTo(3);
    assertThat(iterator.hasNext()).isFalse();
  }

  @Test
  public void testMixedUsage() {
    // Test mixing primitive and boxed iteration on the same iterator
    ImmutableIntArray intArray = ImmutableIntArray.of(1, 2, 3);
    List<Integer> asList = intArray.asList();

    PrimitiveIterator.OfInt primitiveIterator = (PrimitiveIterator.OfInt) asList.iterator();

    // Use nextInt() for first element
    assertThat(primitiveIterator.nextInt()).isEqualTo(1);

    // Use next() for second element (should box)
    assertThat(primitiveIterator.next()).isEqualTo(2);

    // Use nextInt() again for third element
    assertThat(primitiveIterator.nextInt()).isEqualTo(3);

    assertThat(primitiveIterator.hasNext()).isFalse();
  }
}

